using System.Diagnostics;
using System.Reflection;
using System.Runtime.InteropServices;
using Microsoft.Win32;
using XINSkan.Core.Pipeline;
using XINSkan.Models;
using XINSkan.Platform.Windows.IO;
using XINSkan.Security;
using XINSkan.SecurityTests.Infrastructure;

namespace XINSkan.SecurityTests;

/// <summary>
/// Read-Only by Design, checked on what was compiled. The analyzer (RS0030) stops banned calls in source; these
/// tests stop them in IL, including calls generated by the compiler and calls the analyzer cannot see.
/// </summary>
public class ReadOnlyEnforcementTests
{
    private static readonly BannedList Banned = BannedList.Load();

    /// <summary>Assemblies that may only read. Every product assembly except the output writers belongs here.</summary>
    private static readonly Assembly[] ReadOnlyAssemblies =
    [
        typeof(Evidence).Assembly,
        typeof(InvestigationRunner).Assembly,
        typeof(ReadOnlyFile).Assembly,
    ];

    [Fact]
    public void Banned_symbol_list_is_not_empty_and_covers_the_core_operations()
    {
        Assert.Contains("T:System.IO.File", Banned.Types);
        Assert.Contains("T:System.IO.FileStream", Banned.Types);
        Assert.Contains("T:System.Diagnostics.Process", Banned.Types);
        Assert.Contains("M:System.IO.Directory.Delete(System.String,System.Boolean)", Banned.Members);
        Assert.Contains("M:Microsoft.Win32.RegistryKey.SetValue(System.String,System.Object)", Banned.Members);
        Assert.Contains("M:Microsoft.Win32.RegistryKey.OpenSubKey(System.String,System.Boolean)", Banned.Members);
    }

    [Fact]
    public void Every_banned_symbol_resolves_to_a_real_api()
    {
        // A misspelled ID would make the analyzer silently ignore the ban.
        var surface = DocId.PublicSurface(
        [
            typeof(object).Assembly,
            typeof(Process).Assembly,
            typeof(FileSystemWatcher).Assembly,
            typeof(RegistryKey).Assembly,
        ]);

        var unknown = Banned.Entries.Select(e => e.Id).Where(id => !surface.Contains(id)).ToList();
        Assert.Empty(unknown);
    }

    [Fact]
    public void Every_banned_symbol_has_a_reason()
    {
        Assert.Empty(Banned.Entries.Where(e => string.IsNullOrWhiteSpace(e.Reason)).Select(e => e.Id));
    }

    [Fact]
    public void Read_only_assemblies_contain_no_banned_calls()
    {
        var violations = new List<string>();
        foreach (var asm in ReadOnlyAssemblies)
        {
            var (calls, _) = IlScanner.Scan(asm);
            violations.AddRange(calls.Where(Banned.IsBanned).Select(c => $"{asm.GetName().Name}: {c.CallerType}.{c.Caller} -> {c.CalleeDocId}"));
        }

        Assert.Empty(violations);
    }

    [Fact]
    public void All_calls_in_read_only_assemblies_can_be_resolved()
    {
        // An unresolved call could hide a banned one.
        var unresolved = ReadOnlyAssemblies.SelectMany(a => IlScanner.Scan(a).Unresolved).ToList();
        Assert.Empty(unresolved);
    }

    [Fact]
    public void Scanner_detects_a_banned_call_when_one_exists()
    {
        // Guard against a scanner that silently finds nothing: this test assembly does call banned APIs.
        var (calls, _) = IlScanner.Scan(typeof(ReadOnlyEnforcementTests).Assembly);
        Assert.Contains(calls, c => c.CalleeTypeDocId == "T:System.IO.File" && Banned.IsBanned(c));
    }

    [Fact]
    public void In_the_security_assembly_only_the_output_writers_touch_the_file_system()
    {
        var allowed = new[] { typeof(OutputSink).FullName!, typeof(IntegrityManifest).FullName! };
        var (calls, unresolved) = IlScanner.Scan(typeof(OutputSink).Assembly);
        var outside = calls
            .Where(Banned.IsBanned)
            .Where(c => !allowed.Any(a => c.CallerType == a || c.CallerType.StartsWith(a + "+", StringComparison.Ordinal)))
            .Select(c => $"{c.CallerType}.{c.Caller} -> {c.CalleeDocId}")
            .ToList();

        Assert.Empty(outside);
        Assert.Empty(unresolved);
    }

    [Fact]
    public void Only_the_platform_assembly_declares_native_imports()
    {
        var product = new[] { typeof(Evidence).Assembly, typeof(InvestigationRunner).Assembly, typeof(OutputSink).Assembly };
        var imports = product.SelectMany(NativeImports).Select(m => $"{m.DeclaringType}.{m.Name}").ToList();
        Assert.Empty(imports);
    }

    [Fact]
    public void Platform_imports_only_reading_and_querying_functions()
    {
        var entryPoints = NativeImports(typeof(ReadOnlyFile).Assembly)
            .Select(m => m.GetCustomAttribute<DllImportAttribute>()?.EntryPoint ?? m.Name)
            .ToHashSet(StringComparer.Ordinal);

        // Open for reading, query/read device data, read volume and file information, verify a signature offline.
        Assert.Subset(
            new HashSet<string>(StringComparer.Ordinal) { "CreateFileW", "DeviceIoControl", "GetVolumeInformationW", "GetFileInformationByHandle", "WinVerifyTrust", "RegQueryInfoKeyW" },
            entryPoints);
        Assert.NotEmpty(entryPoints);
    }

    [Fact]
    public void Files_and_volumes_are_opened_with_read_access_and_full_sharing()
    {
        var native = typeof(ReadOnlyFile).Assembly.GetType("XINSkan.Platform.Windows.Native.NativeMethods", throwOnError: true)!;
        uint Const(string name) => (uint)native.GetField(name, BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;

        Assert.Equal(0x8000_0000u, Const("GenericRead")); // GENERIC_READ only
        Assert.Equal(0x7u, Const("ShareAll")); // FILE_SHARE_READ | WRITE | DELETE
        Assert.Equal(3u, Const("OpenExisting")); // never CREATE_* or TRUNCATE_EXISTING
    }

    private static IEnumerable<MethodInfo> NativeImports(Assembly asm) =>
        asm.GetTypes()
            .SelectMany(t => t.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.DeclaredOnly))
            .Where(m => (m.Attributes & MethodAttributes.PinvokeImpl) != 0);
}
